import React from "react";
import { StyleSheet, View, ScrollView, Text, Image } from "react-native";
import { Button } from "react-native-elements";
import { useNavigation } from "@react-navigation/native";
import { SvgCssUri } from "react-native-svg";

export default function UserGuest() {
  const navigation = useNavigation();

  return (
    <ScrollView
      centerContent={true}
      contentContainerStyle={{
        marginTop: 30,
      }}
      style={styles.viewBody}
    >
      <SvgCssUri
        style={{ width: 150, height: 75, alignSelf: "center", marginTop: 20 }}
        uri="https://socialagri.com/agriFM/wp-content/themes/agriFM/mobile/img/logo-aginewsfm4.svg"
      />
      <Image
        source={require("../../../assets/img/user-guest.jpg")}
        resizeMode="contain"
        style={styles.image}
      />
      <Text style={styles.title}>Consulta tu perfil de agriFM</Text>
      <Text style={styles.description}>
        Para ir a su perfil, debe registrarse. {"\n"}¡Solo es un minuto y
        gratuito!
      </Text>
      <Text style={styles.description}></Text>
      <View style={styles.viewBtn}>
        <Button
          title="Ver tu perfil"
          buttonStyle={styles.btnStyle}
          containerStyle={styles.btnContainer}
          onPress={() => navigation.navigate("login")}
        />
      </View>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  viewBody: {
    paddingLeft: 30,
    paddingRight: 30,
    backgroundColor: "#422c5e",
  },
  image: {
    height: 150,
    width: "100%",
    marginBottom: 40,
    marginTop: 40,
  },
  title: {
    fontWeight: "bold",
    fontSize: 19,
    marginBottom: 10,
    textAlign: "center",
    color: "#ffffff",
  },
  description: {
    textAlign: "center",
    color: "#ffffff",
  },
  viewBtn: {
    flex: 1,
    alignItems: "center",
  },
  btnStyle: {
    backgroundColor: "#93bf22",
  },
  btnContainer: {
    width: "70%",
  },
});
